// Fetch yesterday's GSC data for each shape
const accessToken = $input.first().json.access_token;
const propertyUrl = $('Loop Properties').first().json.property_url;

const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const dateStr = yesterday.toISOString().split('T')[0];

const shapes = [
  {name: 'query_daily', dimensions: ['query', 'date']},
  {name: 'page_daily', dimensions: ['page', 'date']},
];

const results = [];
for (const shape of shapes) {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://searchconsole.googleapis.com/webmasters/v3/sites/${encodeURIComponent(propertyUrl)}/searchAnalytics/query`,
    headers: {'Authorization': `Bearer ${accessToken}`},
    body: {
      startDate: dateStr,
      endDate: dateStr,
      dimensions: shape.dimensions,
      rowLimit: 25000,
    },
  });
  const rows = response.rows || [];
  for (const row of rows) {
    results.push({
      property_url: propertyUrl,
      shape_name: shape.name,
      data: row,
    });
  }
}

return results.map(r => ({json: r}));
